---@field TipsPopup_Root            UnityEngine.RectTransform   -- 提示(问号,左上角): 打开动画
---@field TipsPopup_BtnClose        UnityEngine.UI.Button       -- 提示(问号,左上角): 关闭按钮
---@field TipsPopup_text            UnityEngine.UI.Text         -- 文本
local MazeUI_TipsPopup = Class('MazeUI_TipsPopup')

-- ========================================================

local KTool = CS.Engine.Lib.KTool
local Text = CS.UnityEngine.UI.Text


function MazeUI_TipsPopup:__init()
    --print("   ~~~~~~~ MazeUI_TipsPopup:__init() ~~~~~~~")
    self.controller = nil
end


function MazeUI_TipsPopup:__delete()
    --print("   ~~~~~~~ MazeUI_TipsPopup:__delete() ~~~~~~~")
end



function MazeUI_TipsPopup:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    --print("   ~~~~~~~ MazeUI_TipsPopup:Awake() ~~~~~~~")
    assert( self.TipsPopup and self.TipsPopup_Root and self.TipsPopup_BtnClose )
    KTool.SetActive(self.controller.gameObject, false);
end


function MazeUI_TipsPopup:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    --print("   ~~~~~~~ MazeUI_TipsPopup:OnDestroy() ~~~~~~~")
end


return MazeUI_TipsPopup
